query:
why does this take the lock twice? I've read it three times and I still don't see what the second one protects:

func (w *Worker) drain() {
	w.mu.Lock()
	pending := w.queue
	w.queue = nil
	w.mu.Unlock()

	for _, job := range pending {
		job.Run()
	}

	w.mu.Lock()
	w.draining = false
	w.mu.Unlock()
}
